import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [clients, setClients] = useState([]);
  const [proveidors, setProveidors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState(null);

  const token = localStorage.getItem('token');

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError(null);
      const res = await fetch('http://localhost/api/comandes', {
        headers: {
          Accept: 'application/json',
          Authorization: token ? `Bearer ${token}` : undefined,
        },
      });
      if (!res.ok) throw new Error('Error al obtenir les comandes');
      const data = await res.json();
      setOrders(Array.isArray(data.dades) ? data.dades : []);
    } catch (err) {
      console.error(err);
      setError(err.message || 'Error al obtenir les comandes');
    } finally {
      setLoading(false);
    }
  };

  const fetchClients = async () => {
    try {
      const res = await fetch('http://localhost/api/clients', {
        headers: { Accept: 'application/json', Authorization: token ? `Bearer ${token}` : undefined }
      });
      if (!res.ok) throw new Error('Error al obtenir els clients');
      const data = await res.json();
      setClients(Array.isArray(data.dades) ? data.dades : []);
    } catch (err) {
      console.error(err.message || err);
    }
  };

  const fetchProveidors = async () => {
    try {
      const res = await fetch('http://localhost/api/proveidors', {
        headers: { Accept: 'application/json', Authorization: token ? `Bearer ${token}` : undefined }
      });
      if (!res.ok) throw new Error('Error al obtenir els proveidors');
      const data = await res.json();
      setProveidors(Array.isArray(data.dades) ? data.dades : []);
    } catch (err) {
      console.error(err.message || err);
    }
  };

  useEffect(() => {
    fetchOrders();
    fetchClients();
    fetchProveidors();
  }, []);

  const handleDelete = async (id) => {
    if (!token) { alert('No estás autenticado. Inicia sesión primero.'); return; }
    if (!window.confirm('Segur que vols eliminar aquesta comanda?')) return;
    try {
      const res = await fetch(`http://localhost/api/comandes/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' }
      });
      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error eliminant comanda');
      setOrders(orders.filter(o => o.id !== id));
      alert(data.missatge);
    } catch (err) {
      alert(err.message);
    }
  };

  const openEditModal = (order) => {
    setEditingOrder({ ...order, client_id: order.client_id || order.client?.id, proveidor_id: order.proveidor_id || order.proveidor?.id });
    setShowModal(true);
  };

  const openCreateModal = () => {
    setEditingOrder({ client_id: '', proveidor_id: '', tipus: '', data: new Date().toISOString().slice(0,10) });
    setShowModal(true);
  };

  const handleChange = (e) => {
    setEditingOrder({ ...editingOrder, [e.target.name]: e.target.value });
  };

  const handleSave = async () => {
    if (!token) { alert('No estás autenticado. Inicia sesión primero.'); return; }
    try {
      const isEditing = !!editingOrder.id;
      const url = isEditing ? `http://localhost/api/comandes/${editingOrder.id}` : `http://localhost/api/comandes`;
      const method = isEditing ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(editingOrder)
      });
      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || (isEditing ? 'Error actualitzant comanda' : 'Error creant comanda'));
      if (isEditing) setOrders(orders.map(o => o.id === editingOrder.id ? editingOrder : o));
      setShowModal(false);
    } catch (err) {
      alert(err.message);
    }
  };


  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  

  return (
    <div className="mt-4">
      <h2>Llista de Comandes</h2>
      <Button variant="primary" className="mb-3" onClick={openCreateModal}>Crear Comanda</Button>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Client</th>
            <th>Proveïdor</th>
            <th>Tipus</th>
            <th>Data</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {orders.length === 0 && (
            <tr><td colSpan="6" className="text-center">No hi ha comandes disponibles</td></tr>
          )}
          {orders.map((order) => (
            <tr key={order.id}>
              <td>{order.id}</td>
              <td>{order.client?.nom || 'Desconegut'}</td>
              <td>{order.proveidor?.nom || 'Desconegut'}</td>
              <td>{order.tipus}</td>
              <td>{new Date(order.data).toLocaleDateString('ca-ES')}</td>
              <td>
                <Button variant="danger" size="sm" onClick={() => handleDelete(order.id)}>
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      {showModal && editingOrder && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog">
            <div className="modal-content">

              <div className="modal-header">
                <h5 className="modal-title">{editingOrder.id ? 'Editar Comanda' : 'Crear Comanda'}</h5>
                <button type="button" className="btn-close" onClick={() => setShowModal(false)} />
              </div>

              <div className="modal-body">
                <select className="form-control mb-2" name="client_id" value={editingOrder.client_id || ''} onChange={(e) => setEditingOrder({ ...editingOrder, client_id: e.target.value })}>
                  <option value="">-- Selecciona client --</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.nom}</option>)}
                </select>
                <select className="form-control mb-2" name="proveidor_id" value={editingOrder.proveidor_id || ''} onChange={(e) => setEditingOrder({ ...editingOrder, proveidor_id: e.target.value })}>
                  <option value="">-- Selecciona proveidor --</option>
                  {proveidors.map(p => <option key={p.id} value={p.id}>{p.nom}</option>)}
                </select>
                <input className="form-control mb-2" name="tipus" value={editingOrder.tipus || ''} onChange={(e) => setEditingOrder({ ...editingOrder, tipus: e.target.value })} placeholder="Tipus" />
                <input type="date" className="form-control" name="data" value={editingOrder.data ? editingOrder.data.slice(0,10) : ''} onChange={(e) => setEditingOrder({ ...editingOrder, data: e.target.value })} />
              </div>

              <div className="modal-footer">
                <Button variant="secondary" onClick={() => setShowModal(false)}>Cancel·lar</Button>
                <Button variant="success" onClick={handleSave}>{editingOrder.id ? 'Guardar' : 'Crear'}</Button>
              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default OrdersList;
